<?php
declare(strict_types=1);

const SV_COMPANY_VISIBILITY_REMEDIATION_CONTRACT='2026-10-25-safety-vote-company-visibility-remediation-r1';
function sv_cvr_normalize($value){if(is_array($value)){if($value===[]||array_keys($value)===range(0,count($value)-1))return array_map('sv_cvr_normalize',$value);ksort($value);foreach($value as$key=>$item)$value[$key]=sv_cvr_normalize($item);}return$value;}
function sv_cvr_hash($value):string{return hash('sha256',json_encode(sv_cvr_normalize($value),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
function sv_cvr_project(array$row):array{return['id'=>(int)($row['id']??0),'campaignCode'=>(string)($row['CampaignCode']??$row['campaignCode']??''),'title'=>(string)($row['TitleTh']??$row['title']??''),'status'=>(string)($row['Status']??$row['status']??''),'discoveryMode'=>(string)($row['DiscoveryMode']??$row['discoveryMode']??''),'rowVersion'=>(int)($row['RowVersion']??$row['rowVersion']??0),'hidden'=>(int)($row['IsHidden']??$row['hidden']??0)===1,'test'=>(int)($row['IsTest']??$row['test']??0)===1];}
function sv_cvr_classify(array$row):array{$item=sv_cvr_project($row);if($item['status']==='Voided')return$item+['decision'=>'excluded','reason'=>'VOIDED_CAMPAIGN'];if($item['hidden']||$item['test'])return$item+['decision'=>'excluded','reason'=>'HIDDEN_OR_TEST'];if($item['discoveryMode']==='public_listing')return$item+['decision'=>'unchanged','reason'=>'ALREADY_COMPANY_WIDE'];if($item['discoveryMode']==='eligible_only')return$item+['decision'=>'remediate','reason'=>'LEGACY_ELIGIBLE_ONLY','targetDiscoveryMode'=>'public_listing'];return$item+['decision'=>'excluded','reason'=>'UNKNOWN_DISCOVERY_MODE'];}
function sv_cvr_plan(array$rows):array{$items=array_map('sv_cvr_classify',$rows);usort($items,function($a,$b){return$a['id']<=>$b['id'];});$candidates=array_values(array_filter($items,function($x){return$x['decision']==='remediate';}));$fingerprint=[];foreach($candidates as$x)$fingerprint[]=['id'=>$x['id'],'campaignCode'=>$x['campaignCode'],'discoveryMode'=>$x['discoveryMode'],'rowVersion'=>$x['rowVersion'],'targetDiscoveryMode'=>$x['targetDiscoveryMode']];$previewHash=sv_cvr_hash(['contract'=>SV_COMPANY_VISIBILITY_REMEDIATION_CONTRACT,'candidates'=>$fingerprint]);return['contract'=>SV_COMPANY_VISIBILITY_REMEDIATION_CONTRACT,'dryRun'=>true,'businessMutation'=>false,'targetDiscoveryMode'=>'public_listing','previewHash'=>$previewHash,'exactConfirmation'=>'REMEDIATE COMPANY VISIBILITY '.strtoupper(substr($previewHash,0,12)),'counts'=>['total'=>count($items),'remediate'=>count($candidates),'unchanged'=>count(array_filter($items,function($x){return$x['decision']==='unchanged';})),'excluded'=>count(array_filter($items,function($x){return$x['decision']==='excluded';}))],'protectedEvidence'=>['eligibility snapshots','eligible voters','participation','ballots','answers','jury assignments/scores','result snapshots/rows','certifications','reports'],'items'=>$items];}
